var LEAD='Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.';
var seed=1;
function rnd(){seed=(seed*1103515245+12345)%2147483648;return seed/2147483648;}
function pick(){return W[Math.floor(rnd()*W.length)];}
function sentence(){
  var n=5+Math.floor(rnd()*12),parts=[];
  for(var i=0;i<n;i++){parts.push(pick());}
  if(n>8&&rnd()>0.5){parts.splice(3+Math.floor(rnd()*3),0,pick()+',');}
  var s=parts.join(' ');
  return s.charAt(0).toUpperCase()+s.slice(1)+'.';
}
function paragraph(){
  var n=3+Math.floor(rnd()*4),out=[];
  for(var i=0;i<n;i++){out.push(sentence());}
  return out.join(' ');
}
function gen(){
  seed=Date.now()%2147483647;
  var c=Math.max(1,Math.min(200,parseInt(document.getElementById('count').value,10)||1));
  var u=document.getElementById('unit').value,classic=document.getElementById('classic').checked,out='';
  if(u==='w'){
    var words=[];
    for(var i=0;i<c;i++){words.push(pick());}
    out=words.join(' ');
    if(classic){out=('lorem ipsum dolor sit amet '+out).split(' ').slice(0,c).join(' ');}
    out=out.charAt(0).toUpperCase()+out.slice(1)+'.';
  } else if(u==='s'){
    var ss=[];
    for(var j=0;j<c;j++){ss.push(j===0&&classic?LEAD:sentence());}
    out=ss.join(' ');
  } else {
    var ps=[];
    for(var k=0;k<c;k++){ps.push(k===0&&classic?LEAD+' '+paragraph():paragraph());}
    out=ps.join('\n\n');
  }
  document.getElementById('out').value=out;
  var wc=out.trim().split(/\s+/).filter(Boolean).length;
  document.getElementById('note').textContent=wc+' words, '+out.length+' characters.';
  WT.resize();
}
document.getElementById('go').addEventListener('click',gen);
document.getElementById('copy').addEventListener('click',function(){
  var ok=WT.copy(document.getElementById('out').value);
  document.getElementById('note').textContent=ok?'Copied to clipboard.':'Copy failed, select the text instead.';
});
gen();
